-- 2. Startups on EcosystemSA: newer data (part 2)
update public.startups as s set
  startup_name = coalesce(v.startup_name, s.startup_name), startup_name_ar = v.startup_name_ar,
  website = coalesce(v.website, s.website), stage = coalesce(v.stage, s.stage), sector = coalesce(v.sector, s.sector),
  region = coalesce(v.region, s.region), tags = coalesce(v.tags, s.tags), logo = v.logo,
