-- EcosystemSA descriptions that differ from ours (English and Arabic)
update public.startups as s set startup_description = v.en, startup_description_ar = v.ar
from (values
  ('ST_335', 'Qantara is an art market intelligence and logistics firm built on proprietary data and a curated network of collectors, institutions, and advisors. We help clients acquire, move, and manage art with the precision of a financial service.', 'قنطرة شركة لذكاء سوق الفن وخدماته اللوجستية، مبنية على بيانات خاصة وشبكة مختارة من المقتنين والمؤسسات والمستشارين، تساعد عملاءها على اقتناء الأعمال الفنية ونقلها وإدارتها بدقة الخدمات المالية.'),
  ('ST_583', 'Rekaz is a Saudi SaaS platform that helps service businesses manage bookings, subscriptions, customers, payments, invoices, and daily operations from one place. It also provides business websites, WhatsApp integrations for notifications and campaigns, reporting, and online payment tools. Rekaz is built for businesses such as salons, clinics, gyms, spas, academies, chalets, event venues, and other appointment- or subscription-based businesses.', 'ركاز منصة سعودية متكاملة لإدارة أعمال المنشآت الخدمية، تساعد أصحاب الأعمال على إدارة الحجوزات والاشتراكات والعملاء والمدفوعات والفواتير والعمليات اليومية من مكان واحد، كما توفر مواقع إلكترونية للأعمال، وربط واتساب للإشعارات والحملات، والتقارير وأدوات الدفع الإلكتروني. تخدم ركاز الصالونات والعيادات والأندية الرياضية والمنتجعات والأكاديميات والشاليهات وقاعات المناسبات وغيرها من الأنشطة التي تعتمد على الحجوزات أو الاشتراكات.'),
  ('ST_615', 'Create a guide for your doors and easily share smart links with your guests.', 'أنشئ دليلًا إرشاديًا لأبوابك، وشارك روابط ذكية مع ضيوفك بسهولة.'),
  ('ST_619', 'Placeit: a residential real estate brokerage platform that connects landlords, tenants, sellers and buyers using AI.', 'بليسيت: منصة وساطة عقارية تربط بين المؤجر والمستأجر والبائع والمشتري باستخدام الذكاء الاصطناعي.'),
  ('ST_636', 'Nashir is a modern Saudi platform for managing and deploying software projects easily and professionally. It lets companies and developers run their applications on their own servers, on cloud servers, or on servers provided by Nashir as a complete, ready solution. It combines fast launches, secure infrastructure and automated operations such as deployment, updates, monitoring and backups, turning server management from a technical burden into a smooth service so you can focus on your product and growth.', 'ناشر منصة سعودية حديثة لإدارة ونشر المشاريع البرمجية بسهولة واحترافية، تمكّن الشركات والمطورين من تشغيل تطبيقاتهم على خوادمهم الخاصة أو خوادم سحابية أو عبر خوادم يوفرها ناشر كحل متكامل وجاهز. تجمع المنصة بين سرعة الإطلاق وأمان البنية التحتية وأتمتة العمليات مثل النشر والتحديث والمراقبة والنسخ الاحتياطي، لتحوّل إدارة الخوادم والنشر من عبء تقني إلى خدمة سلسة تركّز فيها على تطوير منتجك ونمو أعمالك.'),
  ('ST_638', 'Byondbites turns what''s already in your kitchen into meals you actually want to eat. Byondbites is a food tech app that lets users scan their pantry and instantly get personalized recipe ideas based on what they have. We solve a simple but daily problem: food waste and mealtime decision fatigue. The app is live on iOS and Android with an active and growing user base across Saudi Arabia and the UAE. We are currently raising our pre-seed round to fuel growth and the launch of Phase 2, which brings an AI-powered experience. Our expansion path: Saudi Arabia and UAE, then full GCC, then South Asia.', 'يحوّل Byondbites ما في مطبخك إلى وجبات تحب تناولها: تطبيق تقنية غذائية يتيح مسح محتويات المخزن والحصول فورًا على وصفات مخصصة، لمعالجة هدر الطعام وحيرة اختيار الوجبات. التطبيق متاح على iOS وAndroid مع قاعدة مستخدمين متنامية في السعودية والإمارات، ويجمع حاليًا جولة ما قبل التمويل الأولي لإطلاق مرحلة ثانية بتجربة مدعومة بالذكاء الاصطناعي، والتوسع في الخليج ثم جنوب آسيا.'),
  ('ST_641', 'Digital Philosophy is a technology company specializing in digital transformation and building integrated digital solutions for companies and organizations. It designs and develops innovative technical solutions that help companies move from traditional processes to effective, flexible and scalable digital systems. Its services include SaaS, and its product Mohassala is an automated, AI-powered financial intelligence platform built for e-commerce merchants in Saudi Arabia that turns scattered financial data into real-time net profit without human intervention.', 'فلسفة رقمية شركة تقنية متخصصة في التحول الرقمي وبناء الحلول الرقمية المتكاملة للشركات والمؤسسات، تركّز على تصميم وتطوير حلول تقنية مبتكرة تساعد الشركات على الانتقال من العمليات التقليدية إلى أنظمة رقمية فعّالة ومرنة وقابلة للتوسع. من خدماتها البرمجيات كخدمة، ومنتجها «محصلة» منصة ذكاء مالي مؤتمتة بالذكاء الاصطناعي مبنية خصيصًا لتجار التجارة الإلكترونية في المملكة، تحوّل البيانات المالية المشتتة إلى صافي ربح لحظي دون تدخل بشري.'),
  ('ST_643', 'A Saudi gifting marketplace for flowers, cakes, sweets, and occasion products, connecting customers with nearby local stores through a fast and elegant experience.', 'غلوردا منصة سعودية للهدايا والمناسبات تجمع أفضل متاجر الورود والكيك والحلويات والهدايا في تطبيق واحد، مع تجربة شراء سريعة وراقية تعتمد على موقع العميل.'),
  ('ST_646', 'An educational platform that aims to build a tech-savvy entrepreneurial generation through courses in programming, robotics, artificial intelligence and mental arithmetic for children aged 5 to 17, with flexible, live Arabic curricula.', 'منصة تعليمية تسعى لبناء جيل ريادي تقني من خلال دوراتها في البرمجة والروبوت والذكاء الاصطناعي والحساب الذهني المخصصة للأطفال من عمر 5 إلى 17 عامًا، بمناهج عربية وتعليم مرن ومباشر.'),
  ('ST_647', 'An innovative technology platform that aims to transform tech hiring in Saudi Arabia. It brings together Saudi companies looking for specialized tech talent and experienced Arab tech professionals seeking distinctive, flexible job opportunities, and also supports startups in strengthening their business and expanding their services, all in one integrated place.', 'منصة تقنية مبتكرة تهدف إلى إحداث نقلة نوعية في مجال التوظيف التقني بالمملكة العربية السعودية، تجمع الشركات السعودية الراغبة في استقطاب كفاءات تقنية متخصصة مع المواهب التقنية العربية من أصحاب الخبرة المتوسطة والعالية الباحثين عن فرص عمل مميزة ومرنة، إضافة إلى دعم الشركات الناشئة لتعزيز أعمالها وتوسيع نطاق خدماتها في مكان واحد متكامل.'),
  ('ST_650', 'A Saudi AI-powered platform that enables lawyers and legal teams to analyze contracts and draft memoranda and lawsuits with high accuracy. It offers a smart search engine covering more than 450 Saudi laws and regulations, cutting hours of research and manual work down to seconds, and advanced services that raise team efficiency by up to 70% with up to 99% output accuracy.', 'منصة سعودية مدعومة بالذكاء الاصطناعي تهدف إلى تمكين المحامين والفرق القانونية من تحليل العقود وصياغة المذكرات والدعاوى بدقة عالية، وتوفر محرك بحث ذكيًا يغطي أكثر من 450 نظامًا ولائحة سعودية، مما يقلص ساعات البحث والعمل اليدوي إلى ثوانٍ معدودة، مع خدمات متقدمة ترفع كفاءة الفرق بما يصل إلى 70% وبدقة مخرجات تصل إلى 99%.'),
  ('ST_658', 'wcloud.sa is a managed cloud deployment service for non-technical founders who build their apps with AI coding tools like Bolt, Lovable, and Replit. We take the finished code, deploy it on secure cloud infrastructure, and handle the hosting and maintenance.', 'خدمة نشر سحابي مُدار للمؤسسين غير التقنيين الذين يبنون تطبيقاتهم بأدوات الذكاء الاصطناعي مثل Bolt وLovable وReplit؛ نأخذ الكود الجاهز، ونرفعه على بنية سحابية آمنة، ونتولى التشغيل والصيانة.'),
  ('ST_669', 'Sabura is an Arabic educational platform that gives teachers an interactive classroom screen and a set of smart tools to manage lessons and class activities from one place. It works directly in the browser and helps teachers and schools deliver more interactive and organized lessons, both in the classroom and in distance learning.', 'سبورة منصة تعليمية عربية توفر للمعلمين شاشة صف تفاعلية ومجموعة من الأدوات الذكية لإدارة الحصص والأنشطة الصفية من مكان واحد، تعمل مباشرة عبر المتصفح، وتساعد المعلمين والمدارس على تقديم دروس أكثر تفاعلًا وتنظيمًا، سواء داخل الفصل أو في التعليم عن بُعد.'),
  ('ST_670', 'SaffronBoxes is a store in Saudi Arabia specializing in authentic, premium saffron, offering a variety of saffron types for Arabic and Saudi coffee, cooking, hospitality and gifts, including Super Negin, Abu Shal and Abu Shaiba saffron in several weights. It also offers saffron packs, saffron gift boxes, serving sets and accessories.', 'صندوق الزعفران متجر متخصص في الزعفران الأصلي والفاخر في المملكة، يقدّم تشكيلة متنوعة من أنواع الزعفران للقهوة العربية والسعودية والطبخ والضيافة والهدايا، منها زعفران سوبر نقيل وأبو شال وأبو شيبة بأوزان متعددة، إضافة إلى بكجات الزعفران وصناديق الهدايا وتقديمات الزعفران وملحقاته.')
) as v(startup_id, en, ar)
where s.startup_id = v.startup_id;

-- 3. Startups that were missing
insert into public.startups (startup_id, startup_name, startup_name_ar, website, stage, sector, region, tags, logo, country, ecosystemsa_profile_url, startup_description, startup_description_ar) values
  ('ST_1129', 'MyEx', 'ماي إكس', 'https://www.my-ex.app', 'Pre-Seed', 'Retail & E-commerce; Technology; Marketing & Advertising', 'Riyadh', 'Marketplace, Affiliate Marketing, Adtech', 'https://lyacndabmtldhavdgaqn.supabase.co/storage/v1/object/public/contribution-logos/contributions/562f751b-d588-43d6-97f5-396c16e44f24.png', 'Saudi Arabia', 'https://ecosystemsa.com/modules/startups/598c7589-39fa-47e1-ae4f-80e27eee7e8c', 'MyEx is a Saudi technology platform that turns real customer experiences into a trusted source, helping people make more informed buying decisions and helping brands and stores understand customer experience, build trust and reach audiences with real purchase intent. Customers share real experiences after using products or services as short videos, photos, text and detailed ratings, which are reviewed by people before publishing. The platform uses AI to organize content, improve search and discovery, and suggest related experiences and products, and links experiences to stores, offers and purchase links by country. MyEx operates from Saudi Arabia with a presence in the UAE, Bahrain, Oman, Qatar and Egypt.', 'ماي إكس منصة تقنية سعودية تحوّل تجارب العملاء الحقيقية إلى مصدر موثوق يساعد الأفراد على اتخاذ قرارات شراء أكثر وعيًا، ويساعد العلامات التجارية والمتاجر على فهم تجربة العميل وبناء الثقة والوصول إلى جمهور لديه نية شرائية حقيقية. ينشر العملاء تجارب واقعية بعد استخدام المنتجات أو الخدمات بصيغ متعددة تشمل الفيديو القصير والصور والنصوص والتقييمات التفصيلية، وتُراجع بشريًا قبل نشرها. تستفيد المنصة من الذكاء الاصطناعي في تنظيم المحتوى وتحسين البحث والاكتشاف واقتراح التجارب والمنتجات ذات الصلة، وتربط التجارب بالمتاجر والعروض وروابط الشراء حسب البلد، وتعمل من السعودية مع حضور في الإمارات والبحرين وعُمان وقطر ومصر.'),
  ('ST_1130', 'عقارتكس', 'عقارتكس', 'https://aqartix.app/', 'Pre-Seed', 'Real Estate', 'Riyadh', 'SaaS, PropTech', 'https://lyacndabmtldhavdgaqn.supabase.co/storage/v1/object/public/contribution-logos/contributions/3412de1c-c508-4e3f-a050-d216bc5c66c0.jpg', 'Saudi Arabia', 'https://ecosystemsa.com/modules/startups/40cee666-8f0f-4a75-bd07-94456dbdd2e5', 'Aqartex is property management software that helps owners and property managers manage units, tenants, contracts, rents, collection, expenses and financial reports from one place, with smart alerts and easy management from a mobile phone.', 'عقارتكس برنامج لإدارة العقارات والأملاك يساعد الملاك ومديري العقارات على إدارة الوحدات والمستأجرين والعقود والإيجارات والتحصيل والمصروفات والتقارير المالية من مكان واحد، مع تنبيهات ذكية وسهولة في إدارة العقارات من الجوال.'),
  ('ST_1131', 'Qistna', 'قسطنا', 'https://qistna.com/', 'Pre-Seed', 'Financial Services & Fintech', 'Riyadh', 'Financial Solution, Loans, Comparison', 'https://lyacndabmtldhavdgaqn.supabase.co/storage/v1/object/public/contribution-logos/contributions/ecd430c0-561d-48fc-8ca2-6dfb60f81f15.png', 'Saudi Arabia', 'https://ecosystemsa.com/modules/startups/7e26660f-ca1e-4791-84ce-58e2adf13860', 'Qistna is an independent Arabic personal-finance site for Saudi consumers: calculators and comparisons for installments, salary, SIMAH, and repayment. Estimates only, not a lender.', 'قسطنا موقع عربي مستقل للتثقيف المالي في السعودية: حاسبات ومقارنات للأقساط والراتب وسمة والسداد. تقديرات فقط، ولسنا جهة تمويل.')
on conflict (startup_id) do nothing;

commit;
